css:
.d-clearable-input{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-clearable-input *,.d-clearable-input *::before,.d-clearable-input *::after{box-sizing:border-box}
.d-clearable-input [hidden]{display:none!important}
.d-clearable-input .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-clearable-input .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-clearable-input label{display:block;margin:8px 0}
.d-clearable-input input,.d-clearable-input select,.d-clearable-input textarea,.d-clearable-input button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-clearable-input input:not([type=checkbox]):not([type=radio]),.d-clearable-input select,.d-clearable-input textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-clearable-input button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-clearable-input button:disabled{opacity:.5;cursor:default}
.d-clearable-input :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-clearable-input [aria-invalid=true]{border-color:var(--warn)!important}
.d-clearable-input .d-scroll{max-width:100%;overflow:auto}
.d-clearable-input table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-clearable-input th,.d-clearable-input td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-clearable-input caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-clearable-input progress{width:100%;accent-color:var(--ink)}
.d-clearable-input pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-clearable-input h3,.d-clearable-input p{margin:8px 0}
.d-clearable-input [aria-pressed=true],.d-clearable-input [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-clearable-input .d-grow{flex:1;min-width:100px}
.d-clearable-input summary{cursor:pointer;padding:6px 0}
.d-clearable-input ul,.d-clearable-input ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const input=q('[data-input]'),clear=q('[data-clear]');const sync=()=>{clear.disabled=!input.value;};input.oninput=sync;clear.onclick=()=>{input.value='';sync();input.focus();input.dispatchEvent(new Event('input',{bubbles:true}));say('输入已清空');};sync();})(root, q, qa, say);
}
